head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDFIL35700";
scwin.loadedTab = [];   // 이미 초기화한 탭. 탭마다 한 번만 조회하려고 둔다.
scwin.feeRate = 0;    // 고른 조건에 맞는 요율. 계산할 때 쓴다.
scwin.totalCount = 0;   // 마지막 조회의 전체 건수. 전체 다운로드에서 쓴다.
scwin.pageIndex = 1;   // 현재 페이지
scwin.pageItemCnt = 15;   // 페이지당 건수. 셀렉트박스 첫 항목과 같은 값이어야 한다.

// 원본 : ULDFIL35700 상장수수료 (/ui/lst/helper/ULDFIL35700.xml)

/*
 * 화면 동작
 * [수수료 계산 탭]
 *   1. 화면 로딩시 입력할 빈 행을 표시
 *   2. 「시장구분」 「상장방식」 「수수료구분」 선택시 해당 요율을 표시
 *   3. 수량과 단가 입력시 행 금액과 합계를 자동 계산
 *   4. 「행추가」 「행삭제」 「초기화」 「인쇄」 제공
 *
 * [납부 내역 탭]
 *   1. 탭을 처음 열 때 최근 1년 기간으로 조회
 *   2. 기간 버튼 또는 직접 입력한 기간으로 「조회」
 *   3. 「엑셀」 은 현재 페이지분, 「전체 엑셀」 은 조건에 맞는 전체를 다운로드
 *
 * 원본과 달라진 곳
 * - 원본은 기간 계산을 new Date() 로 직접 했다. 월말·윤년에서 어긋나므로 $c.date 로 바꿨다.
 * - 원본은 페이지 수를 화면에서 직접 세어 pageList 에 넣었다. $c.sbm.setPagingInfo 로 바꿨다.
 *
 */

// 화면 상태값

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        // 초기화 함수
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil35700-ref.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    // 처음 열리는 탭을 상수로 직접 지정한다.
    // onpageload 시점에는 탭이 아직 그려지지 않아 getSelectedIndex() 가
    // 기대한 값을 주지 않는다. 그 값을 그대로 쓰면 첫 탭이 초기화되지 않고,
    // 탭을 한 번 눌러야 데이터가 나오는 증상이 생긴다.
    await scwin.initTab(0);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tac_main_ontabclick
 * @description 탭 클릭. 처음 여는 탭이면 그때 준비한다.
 * @param {String} tabId 탭 id
 * @param {Number} index index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tac_main_ontabclick = async function (tabId, index) {
    try {
        await scwin.initTab(index);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil35700-ref.tac_main_ontabclick" });
    }
};

/**
 * @method
 * @name rd_calcCond_onviewchange
 * @description 계산 조건 변경. 세 라디오가 이 핸들러 하나를 함께 쓴다.
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_calcCond_onviewchange = function (info) {
    try {
        scwin.setFeeRate();

        // 조건이 바뀌면 이미 입력한 값의 결과도 달라진다. 바로 다시 계산한다.
        scwin.calcAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil35700-ref.rd_calcCond_onviewchange" });
    }
};

/**
 * @method
 * @name btn_calc_onclick
 * @description 계산 버튼 클릭.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_calc_onclick = function (e) {
    try {
        scwin.calcAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil35700-ref.btn_calc_onclick" });
    }
};

/**
 * @method
 * @name btn_calcReset_onclick
 * @description 초기화 버튼 클릭. 입력과 합계를 함께 비운다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_calcReset_onclick = function (e) {
    try {
        // 조건도 함께 처음 값으로 되돌린다. 입력만 비우면 조건이 남아 결과가 달라 보인다.
        dma_calcCond.reset();

        scwin.setFeeRate();
        scwin.setCalcRows();
        scwin.clearTotal();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil35700-ref.btn_calcReset_onclick" });
    }
};

/**
 * @method
 * @name btn_rowAdd_onclick
 * @description 행추가 버튼 클릭. 입력할 빈 행을 하나 더 만든다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_rowAdd_onclick = function (e) {
    try {
        scwin.addCalcRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil35700-ref.btn_rowAdd_onclick" });
    }
};

/**
 * @method
 * @name btn_rowDelete_onclick
 * @description 행삭제 버튼 클릭. 선택한 행을 지우고 합계를 다시 낸다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_rowDelete_onclick = function (e) {
    try {
        scwin.removeCalcRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil35700-ref.btn_rowDelete_onclick" });
    }
};

/**
 * @method
 * @name dlt_calc_oncelldatachange
 * @description 계산 표의 셀 값 변경. 그 행만 다시 계산한다.
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.dlt_calc_oncelldatachange = function (info) {
    try {
        // 금액 컬럼은 계산 결과라 되받아 계산하지 않는다. 빼면 무한히 되돈다.
        if (info.colID === "amt") return;

        // 숫자만 받는 컬럼에 문자가 들어오면 되돌린다.
        // inputType 이 text 라 입력 자체는 막히지 않으므로 여기서 거른다.
        if (["qty", "unitAmt"].includes(info.colID) && !scwin.isNumeric(info.newValue)) {
            $c.win.alert("숫자만 입력할 수 있습니다.");
            dlt_calc.setCellData(info.rowIndex, info.colID, info.oldValue ?? "");
            return;
        }

        scwin.calcRow(info.rowIndex);
        scwin.calcTotal();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil35700-ref.dlt_calc_oncelldatachange" });
    }
};

/**
 * @method
 * @name btn_rules_onclick
 * @description 계산원칙 버튼 클릭. 규정 안내를 새 창으로 연다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_rules_onclick = function (e) {
    try {
        // 안내 페이지 주소. 업무 규정 페이지로 바꾼다.
        const ruleUrl = "";

        // 주소를 채우기 전에는 밖으로 나가지 않는다.
        if ($c.util.isEmpty(ruleUrl)) {
            $c.win.alert("계산원칙 안내 주소가 설정되지 않았습니다.");
            return;
        }

        $c.win.openExternalPage(ruleUrl);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil35700-ref.btn_rules_onclick" });
    }
};

/**
 * @method
 * @name btn_calcPrint_onclick
 * @description 인쇄 버튼 클릭. 현재 화면을 인쇄한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_calcPrint_onclick = async function (e) {
    try {
        await $c.win.print();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil35700-ref.btn_calcPrint_onclick" });
    }
};

/**
 * @method
 * @name btn_period_onclick
 * @description 기간 버튼 클릭. 버튼 하나로 여러 기간을 처리한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_period_onclick = function (e) {
    try {
        // 예: userData1="M:1" 이면 1개월 전, "D:7" 이면 7일 전
        const userData = this.getUserData("userData1") ?? "";
        const [unit, amount] = userData.split(":");

        const endDate = $c.date.getServerDateTime("yyyyMMdd");
        let startDate = endDate;

        // 날짜 가감은 공통함수를 쓴다. Date 객체로 직접 계산하면 월말·윤년에서 어긋난다.
        if (unit === "D") {
            startDate = $c.date.addDate(endDate, -Number(amount));
        } else if (unit === "M") {
            startDate = $c.date.addMonth(endDate, -Number(amount));
        } else if (unit === "Y") {
            startDate = $c.date.addYear(endDate, -Number(amount));
        }

        cal_startDate.setValue(startDate);
        cal_endDate.setValue(endDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil35700-ref.btn_period_onclick" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 조회 버튼 클릭. 첫 페이지부터 다시 읽는다.
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function (e) {
    try {
        await scwin.searchList(1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil35700-ref.btn_search_onclick" });
    }
};

/**
 * @method
 * @name sel_perPage_onviewchange
 * @description 페이지당 건수 변경. 건수가 바뀌면 페이지 구성이 달라져 첫 페이지부터 읽는다.
 * @param {Object} info 이벤트 정보 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sel_perPage_onviewchange = async function (info) {
    try {
        scwin.pageItemCnt = Number(info.newValue);

        await scwin.searchList(1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil35700-ref.sel_perPage_onviewchange" });
    }
};

/**
 * @method
 * @name btn_excel_onclick
 * @description 현재 페이지 엑셀 다운로드 버튼 클릭.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_excel_onclick = function (e) {
    try {
        if (dlt_list.getRowCount() === 0) {
            $c.win.alert("조회된 내용이 없습니다.");
            return;
        }

        scwin.downloadExcel(`ULDFIL35700_납부내역_${$c.date.getServerDateTime($p, "yyyyMMddHHmmss")}.xlsx`);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil35700-ref.btn_excel_onclick" });
    }
};

/**
 * @method
 * @name btn_excelAll_onclick
 * @description 전체 엑셀 다운로드 버튼 클릭.
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_excelAll_onclick = async function (e) {
    try {
        if (dlt_list.getRowCount() === 0) {
            $c.win.alert("조회된 내용이 없습니다.");
            return;
        }

        if (scwin.totalCount > 5000) {
            $c.win.alert("한 번에 내려받을 수 있는 건수는 "
                + $c.num.formatNumber(5000) + "건입니다.\n조회조건을 좁혀 주세요.");
            return;
        }

        // 오래 걸릴 수 있는 작업은 시작 전에 건수를 알려주고 확인을 받는다.
        if (!await $c.win.confirm($c.num.formatNumber(scwin.totalCount) + "건을 모두 내려받습니다. 계속하시겠습니까?")) return;

        const allRows = await scwin.selectAllRows();

        if ($c.util.isEmpty(allRows)) return;

        // 전체를 그리드에 잠시 올린다.
        dlt_list.setJSON(allRows);

        scwin.downloadExcel(`ULDFIL35700_납부내역_전체목록_${$c.date.getServerDateTime($p, "yyyyMMddHHmmss")}.xlsx`);

        // 원래 보고 있던 페이지로 되돌린다. 이 줄이 없으면 목록이 전체 상태로 남는다.
        await scwin.searchList(scwin.pageIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil35700-ref.btn_excelAll_onclick" });
    }
};

/**
 * @method
 * @name btn_print_onclick
 * @description 인쇄 버튼 클릭. 체크한 행을 인쇄한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_print_onclick = function (e) {
    try {
        const checkedRows = grd_list.getCheckedIndex("chk");

        if ($c.util.isEmpty(checkedRows)) {
            $c.win.alert($c.data.getMessage("com_crud_0199", "인쇄할 행"));
            return;
        }

        const targetNoList = checkedRows.map(rowIndex => dlt_list.getCellData(rowIndex, "bzProcsNo"));

        // 보고서가 정해지면 아래를 살린다. 인자는 보고서 규격에 맞춘다.
        // $c.data.openReportPdf("RLDFIL00000", { bzProcsNoList : targetNoList });
        $c.win.alert("인쇄 대상 " + targetNoList.length + "건\n" + targetNoList.join(", "));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil35700-ref.btn_print_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchList
 * @description 조회 탭 목록 조회. 페이지 번호를 받아 그 페이지를 읽는다.
 * @param {Number} index index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function (index) {
    scwin.pageIndex = index ?? 1;

    // 자기 회사 자료만 보이도록 회사코드를 조회조건에 싣는다.
    // 세션에서 읽는다. 화면에서 따로 조회하면 통신이 늘고 값이 세션과 어긋날 수 있다.
    dma_search.set("isurCd", $c.session.getUserInfo("isurCd"));

    dma_search.set("page", scwin.pageIndex);
    dma_search.set("size", scwin.pageItemCnt);

    const sbmOptions = {
        id : "sbm_searchList",
        method : "get",
        action : "/api/listing/support/oneline-issue/listfee/select-list-receipt",
        ref : "dma_search",
        target : "dlt_list=body.content",
        gridview : "grd_list",
        isProcessMsg : false
    };

    // 통신 오류 시 reject 되므로 catch 로 받는다. 사용자 안내는 공통 오류 핸들러가 한다.
    const result = await $c.sbm.executeDynamic(sbmOptions);

    scwin.setPagingInfo(result);
};

/**
 * @method
 * @name selectAllRows
 * @description 조회조건에 맞는 전체를 한 번에 읽어 배열로 돌려준다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectAllRows = async function () {
    // 조회조건은 그대로 두고 페이지만 전체로 바꿔 부른다.
    dma_search.set("page", 1);
    dma_search.set("size", scwin.totalCount);

    const sbmOptions = {
        id : "sbm_selectAllRows",
        method : "get",
        action : "/api/listing/support/oneline-issue/listfee/select-list-receipt",
        ref : "dma_search",
        // 그리드에 꽂지 않는다. 응답만 받아 호출한 쪽에 돌려준다.
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);

    return result.responseJSON?.body?.content ?? [];
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setPagingInfo
 * @description 페이징 컴포넌트를 설정한다.
 * @param {*} result result
 * @returns {void}
 * @hidden N
 */
scwin.setPagingInfo = function (result = {}) {
    const pagingInfo = {
        pageType : "P",       // S/P/A. 기본 P
        rowNumVisble : "grd_list|asc",   // 그리드 행 번호를 전체 순번으로 매긴다
        maxRowNum : scwin.pageItemCnt,   // 그리드에 한 번에 보일 행 수
        pageListId : "pgl_list",     // 페이지 리스트 아이디
        pageFunction : "scwin.searchList",  // 페이지 번호를 눌렀을 때 부를 함수
        currentPage : scwin.pageIndex,
        recordCountPerPage : scwin.pageItemCnt, // 반드시 넘길 것
        totalCountId : "txt_totalCnt",   // 전체 건수를 출력할 컴포넌트
        pageSize : 10       // 한 번에 보일 페이지 번호 개수
    };

    scwin.totalCount = result.responseJSON?.body?.totalCount ?? 0;

    $c.sbm.setPagingInfo(pagingInfo, "dma_paging", scwin.totalCount);
};

/**
 * @method
 * @name initTab
 * @description 탭을 처음 열 때 한 번만 준비한다.
 * @param {Number} index index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initTab = async function (index) {
    if (scwin.loadedTab.includes(index)) return;

    scwin.loadedTab.push(index);

    if (index === 0) {
        scwin.initCalcTab();
    } else if (index === 1) {
        await scwin.initListTab();
    }
};

/**
 * @method
 * @name initCalcTab
 * @description 계산 탭 준비. 입력할 빈 행을 깔아 둔다.
 * @returns {void}
 * @hidden N
 */
scwin.initCalcTab = function () {
    scwin.setCalcRows();

    // 고른 조건에 맞는 요율을 먼저 정한다. 계산이 이 값을 쓴다.
    scwin.setFeeRate();

    // 예시가 채워진 상태를 바로 보여 준다. 빈 표면 계산 결과를 확인할 수 없다.
    scwin.calcAll();
};

/**
 * @method
 * @name setFeeRate
 * @description 고른 조건에 맞는 요율을 정하고 화면에 표시한다.
 * @returns {void}
 * @hidden N
 */
scwin.setFeeRate = function () {
    // 조건별 요율표. 키는 "시장구분-상장방식-수수료구분" 을 이어 붙인 값이다.
    // 실제 업무에서는 요율이 자주 바뀌므로 이 표 대신 서버에서 조회해 쓴다.
    const feeRateTable = {
  "1-1-1" : 0.9, // 유가증권 · 신규상장 · 보통주권
  "1-2-1" : 0.5, // 유가증권 · 추가상장 · 보통주권
  "2-1-1" : 1.2, // 코스닥 · 신규상장 · 보통주권
  "2-2-1" : 0.7, // 코스닥 · 추가상장 · 보통주권
  "3-1-2" : 0.3, // 증권상품 · 신규상장 · 집합투자증권
  "4-1-4" : 0.2 // 신종증권 · 신규상장 · 신주인수권증권
    };

    const key = [
        dma_calcCond.get("marketCd"),
        dma_calcCond.get("listTpCd"),
        dma_calcCond.get("feeTpCd")
    ].join("-");

    // 표에 없는 조합은 기본 요율 1.0 을 쓴다.
    scwin.feeRate = feeRateTable[key] ?? 1.0;

    txt_feeRate.setValue(scwin.feeRate);
};

/**
 * @method
 * @name initListTab
 * @description 조회 탭 준비. 기본 기간을 잡고 한 번 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initListTab = async function () {
    // 서버 일자를 쓴다. new Date() 는 사용자 PC 시각이라 조회 기준이 흔들린다.
    const today = $c.date.getServerDateTime("yyyyMMdd");

    // 기본 조회기간은 업무 성격에 맞춘다. 납부 내역처럼 드문 건은 넓게, 일별 처리 건은 좁게 잡는다.
    cal_endDate.setValue(today);
    cal_startDate.setValue($c.date.addYear(today, -1));

    // 시작일이 종료일보다 뒤면 달력이 스스로 막아 준다. 화면에서 비교문을 쓰지 않는다.
    $c.date.compareFromToDate(cal_startDate, cal_endDate, ["조회 시작일자", "조회 종료일자"], "yyyyMMdd");

    // 조회영역에서 엔터를 치면 조회가 돌게 한다.
    $c.win.setEnterKeyEvent(grp_search, scwin.btn_search_onclick);

    await scwin.searchList(1);
};

/**
 * @method
 * @name setCalcRows
 * @description 계산 표를 처음 상태로 되돌린다.
 * @returns {void}
 * @hidden N
 */
scwin.setCalcRows = function () {
    const rows = [];

    // 사용자가 직접 넣는 표라 빈 행을 깔아 둔다.
    while (rows.length < 10) {
        rows.push({ itemNm : "", qty : "", unitAmt : "", amt : "" });
    }

    dlt_calc.setJSON(rows);
};

/**
 * @method
 * @name addCalcRow
 * @description 계산 표에 빈 행을 하나 추가한다.
 * @returns {void}
 * @hidden N
 */
scwin.addCalcRow = function () {
    dlt_calc.insertRow();
};

/**
 * @method
 * @name removeCalcRow
 * @description 계산 표에서 선택한 행을 지운다.
 * @returns {void}
 * @hidden N
 */
scwin.removeCalcRow = function () {
    const rowIndex = dlt_calc.getRowPosition();

    if (rowIndex < 0) {
        $c.win.alert($c.data.getMessage("com_crud_0199", "삭제할 행"));
        return;
    }

    dlt_calc.removeRow(rowIndex);

    scwin.calcTotal();
};

/**
 * @method
 * @name calcAll
 * @description 전 행을 계산하고 합계를 낸다.
 * @returns {void}
 * @hidden N
 */
scwin.calcAll = function () {
    const rowCount = dlt_calc.getRowCount();

    for (let i = 0; i < rowCount; i++) {
        scwin.calcRow(i);
    }

    scwin.calcTotal();
};

/**
 * @method
 * @name calcRow
 * @description 한 행의 금액을 계산한다.
 * @param {Number} rowIndex 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.calcRow = function (rowIndex) {
    const qty = scwin.toNumber(dlt_calc.getCellData(rowIndex, "qty"));
    const unitAmt = scwin.toNumber(dlt_calc.getCellData(rowIndex, "unitAmt"));

    // 둘 중 하나라도 비면 금액도 비운다. 0 을 넣으면 입력한 것처럼 보인다.
    if (qty === 0 || unitAmt === 0) {
        dlt_calc.setCellData(rowIndex, "amt", "");
        return;
    }

    // 고른 조건의 요율을 곱한다. 소수점이 남지 않게 반올림은 공통함수로 한다.
    const amount = $c.num.round(qty * unitAmt * scwin.feeRate / 100, 0);

    dlt_calc.setCellData(rowIndex, "amt", $c.num.formatNumber(amount));
};

/**
 * @method
 * @name calcTotal
 * @description 합계를 낸다.
 * @returns {void}
 * @hidden N
 */
scwin.calcTotal = function () {
    const rowCount = dlt_calc.getRowCount();

    let totalQty = 0;
    let totalAmt = 0;

    for (let i = 0; i < rowCount; i++) {
        totalQty += scwin.toNumber(dlt_calc.getCellData(i, "qty"));
        totalAmt += scwin.toNumber(dlt_calc.getCellData(i, "amt"));
    }

    txt_totalQty.setValue($c.num.formatNumber(totalQty));
    txt_totalAmt.setValue($c.num.formatNumber(totalAmt));
};

/**
 * @method
 * @name clearTotal
 * @description 합계를 비운다.
 * @returns {void}
 * @hidden N
 */
scwin.clearTotal = function () {
    txt_totalQty.setValue("");
    txt_totalAmt.setValue("");
};

/**
 * @method
 * @name toNumber
 * @description 화면 값을 계산용 숫자로 바꾼다.
 * @param {*} value value
 * @returns {void}
 * @hidden N
 */
scwin.toNumber = function (value) {
    if ($c.util.isEmpty(value)) return 0;

    const num = $c.num.unFormatNumber(value);

    return isNaN(num) ? 0 : Number(num);
};

/**
 * @method
 * @name isNumeric
 * @description 숫자로 볼 수 있는 값인지 판정한다.
 * @param {*} value value
 * @returns {void}
 * @hidden N
 */
scwin.isNumeric = function (value) {
    if ($c.util.isEmpty(value)) return true;

    return $c.num.isNumber($c.num.unFormatNumber(value));
};

/**
 * @method
 * @name downloadExcel
 * @description 현재 그리드를 엑셀로 내려받는다.
 * @param {*} fileName fileName
 * @returns {void}
 * @hidden N
 */
scwin.downloadExcel = function (fileName) {
    const options = {
        fileName : fileName,
        // 셀 배경·글자색을 쓰려면 반드시 켠다. 끄면 CSS 가 무시되어 색이 빠진다.
        useStyle : true,
        // 선택용 체크박스 컬럼은 제외한다.
        removeColumns : "0"
    };

    // 세 번째 인자는 표 위에 얹을 안내행이다. 필요 없으면 빈 배열을 넘긴다.
    $c.data.downloadGridViewExcel(grd_list, options, []);
};

/**
 * @method
 * @name amountFormatter
 * @description 그리드 금액 컬럼 표시 형식. 저장값은 숫자로 두고 보이는 값에만 콤마를 넣는다.
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.amountFormatter = function (data) {
    if ($c.util.isEmpty(data)) return "";

    return $c.num.formatNumber(data);
};

/**
 * @method
 * @name dateFormatter
 * @description 그리드 일자 컬럼 표시 형식. yyyyMMdd 를 yyyy-MM-dd 로 보여준다.
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.dateFormatter = function (data) {
    if ($c.util.isEmpty(data)) return "";

    return $c.date.formatDate(data, "-");
};
